const tasks = [
  ["REMOTE_TREE", "gh api 'repos/open-vela/contest2026_329_dela/git/trees/558bed9a9652921a6e4748c9ef294f05e39ee72c?recursive=1' | ConvertFrom-Json | Select-Object -ExpandProperty tree | Where-Object { $_.path -like 'logs/*' } | Group-Object { if ($_.path -match '^logs/([^/]+)') { $Matches[1] } else { 'root' } } | Select-Object Name,Count"],
  ["REMOTE_MANIFEST", "$b64 = gh api 'repos/open-vela/contest2026_329_dela/contents/logs/pjjuihj/manifest.json?ref=dev-ai-contest-2026' --jq '.content'; [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(($b64 -replace '\\s','')))"],
  ["LOCAL_SESSIONS", "$p = '[REDACTED_LOCAL_PATH]| Sort-Object LastWriteTime -Descending | Select-Object -First 30 FullName,Length,LastWriteTime } else { 'NO_SESSION_DIR' }"],
  ["LOCAL_REPO", "$paths = @('[REDACTED_LOCAL_PATH]"${p}:$(Test-Path -LiteralPath $p)\" }"]
];
const out = await Promise.all(tasks.map(async ([label,cmd]) => {
  const r = await tools.exec_command({cmd, shell:"powershell", login:false, workdir:"[REDACTED_LOCAL_PATH]", max_output_tokens: label==="REMOTE_MANIFEST"?12000:6000, yield_time_ms:10000});
  return {label, output:r.output, exit_code:r.exit_code};
}));
for (const x of out) text(`---${x.label}---\n${x.output}`);

const r = await tools.exec_command({
  cmd: "$tree = gh api 'repos/open-vela/contest2026_329_dela/git/trees/558bed9a9652921a6e4748c9ef294f05e39ee72c?recursive=1' | ConvertFrom-Json; $paths = $tree.tree | Where-Object { $_.type -eq 'blob' -and $_.path -like 'logs/*' } | Select-Object -ExpandProperty path; [pscustomobject]@{total=$paths.Count; codex=($paths | Where-Object { $_ -match '/codex__' }).Count; claude=($paths | Where-Object { $_ -match '/claude-code__' }).Count; manifests=($paths | Where-Object { $_ -match '/manifest\\.json$' }).Count; newest=($paths | Sort-Object)[-1] } | ConvertTo-Json",
  shell: "powershell",
  login: false,
  workdir: "[REDACTED_LOCAL_PATH]",
  max_output_tokens: 4000,
  yield_time_ms: 10000
});
text(r.output);

const r = await tools.exec_command({
  cmd: `$ErrorActionPreference='Stop'
$branches = gh api repos/open-vela/.claude/branches --paginate | ConvertFrom-Json
$branches | ForEach-Object { $_.name }
gh api repos/open-vela/.claude/branches/dev-ai-contest-2026 --jq '{name,sha:.commit.sha}'`,
  workdir: "[REDACTED_LOCAL_PATH]",
  yield_time_ms: 10000,
  max_output_tokens: 12000
});
text(r.output);

