const r = await tools.exec_command({
  cmd: `$ErrorActionPreference='Stop'
$repoDir='[REDACTED_LOCAL_PATH]
if(Test-Path -LiteralPath $repoDir){ throw "staging clone already exists: $repoDir" }
git clone --depth 1 --branch dev-ai-contest-2026 https://github.com/open-vela/contest2026_329_dela.git $repoDir
git -C $repoDir rev-parse HEAD
git -C $repoDir status --short`,
  workdir: "[REDACTED_LOCAL_PATH]",
  yield_time_ms: 30000,
  max_output_tokens: 20000
});
text(r.output);

const r = await tools.exec_command({
  cmd: `$ErrorActionPreference='Stop'
$work='[REDACTED_LOCAL_PATH]
$log=Join-Path $work 'logs\\pjjuihj\\2026-09-19\\codex__01a0b901-7b74-7a72-b7c1-66bc21bab9d7.jsonl'
$manifest=Join-Path $work 'logs\\pjjuihj\\manifest.json'
$events=Get-Content -LiteralPath $log | ForEach-Object { $_ | ConvertFrom-Json }
$m=Get-Content -Raw -LiteralPath $manifest | ConvertFrom-Json
$errors=@()
$required=@('schema_version','session_id','team_id','github_login','tool','seq','ts','role')
for($i=0;$i -lt $events.Count;$i++){
  $e=$events[$i]
  foreach($f in $required){ if($null -eq $e.$f){$errors+="event[$i] missing $f"} }
  if($e.schema_version -ne '1.0'){$errors+="event[$i] schema"}
  if($e.team_id -ne 'contest2026_329_dela'){$errors+="event[$i] team"}
  if($e.github_login -ne 'pjjuihj'){$errors+="event[$i] login"}
  if($e.tool -ne 'codex'){$errors+="event[$i] tool"}
  if($e.seq -ne $i){$errors+="event[$i] seq=$($e.seq)"}
  if($e.role -notin @('user','assistant','tool','system')){$errors+="event[$i] role"}
  if($e.role -eq 'tool' -and ([string]::IsNullOrWhiteSpace($e.tool_name) -or $null -eq $e.tool_call_id)){ $errors+="event[$i] tool fields" }
}
$new=$m.sessions | Where-Object session_id -eq '01a0b901-7b74-7a72-b7c1-66bc21bab9d7'
if($null -eq $new){$errors+='manifest entry missing'}
if($new.event_count -ne $events.Count){$errors+='manifest count mismatch'}
$pathHits=(rg --count-matches -g '*.jsonl' '(?<![A-Za-z0-9])[A-Z]:[\\\\/]|[REDACTED_LOCAL_PATH]' -- $log 2>$null | Out-String).Trim()
