                                          velawear_free_memory());
            runtime_update_ms = now_ms;
          }

        if (g_agent.power_mode == VELAWEAR_POWER_DEEP_SLEEP)
          {
            wait_ms = 100;
          }
        else if (g_agent.power_mode == VELAWEAR_POWER_LIGHT_SLEEP)
          {
            wait_ms = 100;
          }
        else if (g_agent.power_mode == VELAWEAR_POWER_IDLE)
